insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('c001', 'org-demo', '越前和紙', 'えちぜんわし', '越前和紙の里 パピルス館', '予約なしで紙漉き体験ができる施設。所要20〜40分で、漉いた紙はその場で持ち帰れる。隣接する卯立の工芸館では、原料づくりから天日干しまでの全工程を見学できる。', 'https://www.echizenwashi.jp/', '福井県', '福井県越前市新在家町8-44', '越前和紙は1500年の歴史を持つとされる産地。', '和紙,紙漉き,体験できる,文具', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('c002', 'org-demo', '輪島塗', 'わじまぬり', '輪島塗会館（輪島漆器商工業協同組合）', '1階に約60軒の漆器店が出店する共同ショップ、2階に製作工程と歴史の資料展示室がある。輪島塗は百以上の工程を分業でこなす。', 'https://wajimanuri.or.jp/', '石川県', '石川県輪島市河井町24-55', '輪島漆器商工業協同組合が運営。', '漆器,食器,見学できる,沈金', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('c003', 'org-demo', '西陣織', 'にしじんおり', '西陣織会館（西陣織工業組合）', '職人による手織の実演、蚕の飼育や座繰りの見学ができる。手織体験では20×30cm程度のテーブルセンターを織れる。西陣織は工程ごとに職人が分かれる分業制。', 'https://nishijin.or.jp/', '京都府', '京都府京都市上京区西堀川通元誓願寺上ル竪門前町414', '西陣織工業組合が運営。', '織物,絹,帯,体験できる,実演', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('c004', 'org-demo', '南部鉄器', 'なんぶてっき', '岩鋳鉄器館', '南部鉄器の製造工程を無料で見学できる工場併設の資料館。鋳型に文様を一粒ずつ押していくあられ模様の工程が見られる。使うほど内側に膜ができて湯の味が変わる。', 'https://iwachu.co.jp/', '岩手県', '岩手県盛岡市南仙北2-23-9', '南部鉄器は江戸期の藩の保護から発展した。', '金工,鉄,茶道具,見学できる,急須', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d001', 'artisan-demo', '小鹿田焼 飛び鉋の小鉢', 'おんたやき とびかんなのこばち', '（架空）坂本 陽一', '鉋を当てて規則的な刻みを入れる飛び鉋の小鉢。土は地元の山から掘り、唐臼で搗いて作る。素朴で厚みがある。', null, '大分県', '大分県日田市源栄町皿山', '小鹿田焼は江戸中期から続く。一子相伝で作り手を増やさない方針を守っている。', '陶磁器,陶器,器,食器', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d002', 'artisan-demo', '津軽塗 七々子塗の箸', 'つがるぬり ななこぬりのはし', '（架空）工藤 佳子', '菜の花の種を蒔いて模様を作る七々子塗。研ぎ出すと小さな輪が浮かぶ。四十以上の工程を経て仕上がる。', null, '青森県', '青森県弘前市', '藩政時代に始まった塗り。', '漆器,食器,箸', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d003', 'artisan-demo', '琉球ガラス 泡入りのグラス', 'りゅうきゅうがらす あわいりのぐらす', '（架空）比嘉 直人', '廃瓶を溶かして再生した青いガラス。あえて気泡を残しており、光を通すと水中のように見える。厚手で手に重い。', null, '沖縄県', '沖縄県糸満市', '戦後の物資不足で米軍の廃瓶を使ったのが始まり。', 'ガラス,器,食器,夏', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d004', 'artisan-demo', '三味線 紅木の棹', 'しゃみせん こうきのさお', '（架空）遠藤 常吉', 'インド産の紅木を十年以上寝かせてから削り出す棹。継ぎ目が指に触れないよう精度を合わせる。木の詰まり具合で音が変わる。', null, '東京都', '東京都台東区', '棹だけを専門に手がけ、組み立ては別の職人に渡す分業。', '楽器,木工,三味線,音が鳴る', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d005', 'artisan-demo', '尺八 地無し管', 'しゃくはち じなしかん', '（架空）中村 玄樹', '内側に漆を塗り重ねない地無しの竹管。竹そのものの内径で鳴らすため個体差が大きく、息の入れ方で音色が変わる。', null, '京都府', '京都府京都市', '江戸期の虚無僧尺八の作り方を復元。', '楽器,竹,尺八,音が鳴る', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d006', 'artisan-demo', '和太鼓 欅のくり抜き胴', 'わだいこ けやきのくりぬきどう', '（架空）浅野 武', '一本の欅を丸ごとくり抜いた胴。乾燥に数年かけ、割れが出ないのを確かめてから皮を張る。低く長く響く。', null, '石川県', '石川県白山市', '原木の確保が年々難しくなっている。', '楽器,木工,太鼓,音が鳴る', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d007', 'artisan-demo', '駿河竹千筋細工 虫籠', 'するがたけせんすじざいく むしかご', '（架空）杉山 隆一', '丸く削った竹ひごを差し込んで組む籠。接着剤を使わず竹の弾力だけで留める。透けるほど細い。', null, '静岡県', '静岡県静岡市', '江戸後期に武士の内職から広まった。作り手は現在十数人。', '竹工,小物,竹,夏', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d008', 'artisan-demo', '備前焼 緋襷の徳利', 'びぜんやき ひだすきのとっくり', '（架空）森本 一馬', '釉薬を使わず、藁を巻いて焼くと赤い線が走る。窯の中の置き場所で色が決まるため、同じものは二つとない。', null, '岡山県', '岡山県備前市伊部', '備前は釉薬を使わない焼き締めを千年続けている。', '陶磁器,陶器,酒器,器', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d009', 'artisan-demo', '京友禅 手描きの風呂敷', 'きょうゆうぜん てがきのふろしき', '（架空）岡村 貴子', '糊で輪郭を置き、筆で一色ずつ挿していく手描き友禅。色の境が滲まない。淡い色を何度も重ねて深さを出す。', null, '京都府', '京都府京都市', '下絵・糊置き・彩色が別の職人に分かれる分業制。', '染物,布,友禅', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d010', 'artisan-demo', '大館曲げわっぱ 弁当箱', 'おおだてまげわっぱ べんとうばこ', '（架空）佐藤 建二', '秋田杉を煮て柔らかくし、曲げて桜の皮で縫い留める。木が余分な水分を吸うので冷めた米がべたつかない。', null, '秋田県', '秋田県大館市', '藩政期に下級武士の内職として奨励された。', '木工,弁当箱,杉,贈り物', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d011', 'artisan-demo', '江戸切子 魚子紋の冷酒杯', 'えどきりこ ななこもんのれいしゅはい', '（架空）堀口 誠', '色被せガラスの表面を回転砥石で削り、細かい格子を刻む。透明な部分と色の対比が出る。手に取ると角がざらつく。', null, '東京都', '東京都江東区', '幕末に江戸で始まったガラス加工。', 'ガラス,酒器,切子,夏,贈り物', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d012', 'artisan-demo', '高岡銅器 花器', 'たかおかどうき かき', '（架空）般若 秀樹', '鋳込んだ銅に薬品をかけて色を出す着色仕上げ。緑青とも黒ともつかない色に変化する。ずっしり重い。', null, '富山県', '富山県高岡市', '加賀藩が鋳物師を招いたのが始まり。着色は専門の職人が担う。', '金工,銅,花器', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d013', 'artisan-demo', '本場大島紬 泥染めの反物', 'ほんばおおしまつむぎ どろぞめのたんもの', '（架空）肥後 明美', 'テーチ木で染めた糸を泥田に浸して黒く発色させる。泥に含まれる鉄分と反応する。軽くて皺になりにくい。', null, '鹿児島県', '鹿児島県奄美市', '締機・泥染め・織りがそれぞれ別の職人に分かれる。', '織物,絹,紬', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d014', 'artisan-demo', '播州そろばん 樺の玉', 'ばんしゅうそろばん かばのたま', '（架空）宮永 敏夫', '樺の玉を一粒ずつ削り、竹の軸に通す。指で弾いたときの音と止まり方が揃うよう玉の重さを合わせる。', null, '兵庫県', '兵庫県小野市', '玉・軸・枠が別々の職人による分業。', '木工,文具,そろばん,音が鳴る', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d015', 'artisan-demo', '岩谷堂箪笥 鉄製手掛かり', 'いわやどうたんす てつせいてがかり', '（架空）及川 正', '欅の箪笥に打つ手打ちの鉄金具。唐草を透かし彫りにする。木地師と金具師が別々に作り、最後に合わせる。', null, '岩手県', '岩手県奥州市', '金具を打てる職人が減っている。', '木工,家具,金具', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d016', 'artisan-demo', '丸亀うちわ 平柄', 'まるがめうちわ ひらえ', '（架空）香川 実', '一本の竹を割いて骨と柄を一体で作る平柄。骨が細かいほど風が柔らかい。和紙を貼って縁を留める。', null, '香川県', '香川県丸亀市', '金比羅参りの土産として江戸期に広まった。', '竹工,うちわ,夏,贈り物', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d017', 'artisan-demo', '紅型', 'びんがた', '（架空）比嘉 光男', '型紙を彫り、防染糊を置いてから顔料を指で摺り込む型染め。一色ごとに天日で乾かしてから次の色を挿すため、七色使うと七回乾かす。型紙は自分で彫り、同じ図案は二度と彫らない。', null, '沖縄県', '沖縄県那覇市', '琉球王国時代に王族・士族の衣装として発展した。', '染物,布,型染め', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d018', 'artisan-demo', '会津型染め', 'あいづかたぞめ', '（架空）猪苗代 悦子', '型紙を彫るのに十日、糊を置いて染めるのに五日かかる型染め。糊は餅粉と糠を練って自分で作る。乾く前に触ると柄が崩れるため、一枚仕上げるまで一切触らない。', null, '福島県', '福島県会津若松市', '会津は藍染の産地として江戸期から知られる。', '染物,布', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d019', 'artisan-demo', '阿波藍染', 'あわあいぞめ', '（架空）三木 保', 'すくもを発酵させた藍甕に、糸や布を二十回以上浸けては空気に触れさせて発色させる。甕は毎日かき混ぜて温度と発酵具合を確かめる。浸ける回数で色の濃さが変わる。', null, '徳島県', '徳島県徳島市', '阿波藍は江戸期に全国の藍の大半を占めた。', '染物,布,藍', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d020', 'artisan-demo', '出雲藍染', 'いずもあいぞめ', '（架空）錦織 保', '地元産の蓼藍から作ったすくもだけを使う藍染め。化学建てはせず、灰汁と発酵の力だけで染液を建てる。建てるのに二週間、安定させるのにさらに一週間かかる。', null, '島根県', '島根県松江市', '出雲地方では明治期まで藍作が盛んだった。', '染物,布,藍', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d021', 'artisan-demo', '因州和紙', 'いんしゅうわし', '（架空）山根 修一', '楮の皮を煮て叩き、簀桁を前後に振って漉く流し漉き。一枚を漉くのに数十秒だが、乾燥まで含めると二日かかる。厚みを均一にするため、桁を振る回数を数えながら漉く。', null, '鳥取県', '鳥取県鳥取市', '因州和紙は書道用紙の産地として知られる。', '和紙,文具', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d022', 'artisan-demo', '土佐和紙', 'とさわし', '（架空）川村 悠', '楮・三椏・雁皮の三種を漉き分ける。雁皮は繊維が短く扱いにくいため、一人前になるまで五年はかかるとされる。漉いた紙は板に貼って天日で乾かす。', null, '高知県', '高知県いの町', '土佐和紙は千年以上前から漉かれてきたとされる。', '和紙,紙漉き,文具', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d023', 'artisan-demo', '石州和紙', 'せきしゅうわし', '（架空）佐々木 昭二', '楮の繊維を三日かけて煮て精製し、トロロアオイの粘りを加えて漉く。強度を出すため繊維を短く切らずに漉くのが特徴で、破れにくい紙になる。', null, '島根県', '島根県浜田市', '石州和紙は障子紙の産地として発展した。', '和紙,紙漉き', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d024', 'artisan-demo', '八女和紙', 'やめわし', '（架空）松尾 光一', '地元の提灯や傘に使う和紙を、楮を原料に手漉きする。一日に漉けるのは百数十枚ほどで、天候によって乾燥時間が半日から一日変わる。', null, '福岡県', '福岡県八女市', '八女は提灯の産地として和紙の需要が生まれた。', '和紙,文具', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d025', 'artisan-demo', '有田焼', 'ありたやき', '（架空）深川 誠一', '陶石を砕いて練った磁土を轆轤で挽き、九百度前後で素焼きしたあと絵付けをして本焼きする。呉須で下絵を描き、上絵付けをする場合はさらに三度目の焼成を行う。', null, '佐賀県', '佐賀県有田町', '有田は日本で最初に磁器が焼かれた産地とされる。', '陶磁器,陶器,食器', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d026', 'artisan-demo', '萩焼', 'はぎやき', '（架空）坂田 芳雄', '土を数種類調合し、低い温度でじっくり焼き締める。貫入と呼ぶ細かいひびに茶渋が入り、使うほど色が変わる「萩の七化け」と呼ばれる特徴がある。', null, '山口県', '山口県萩市', '萩焼は朝鮮から渡った陶工が始めたとされる。', '陶磁器,陶器,茶道具', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d027', 'artisan-demo', '壺屋焼', 'つぼややき', '（架空）新垣 勝', '泥釉と呼ぶ黒っぽい釉薬をかけて焼く荒焼と、白化粧を施す上焼の二種を手がける。登り窯での焼成には丸一日かけ、薪の投入を交代で続ける。', null, '沖縄県', '沖縄県那覇市', '壺屋は琉球王府が窯場を集めて作った町。', '陶磁器,陶器,酒器', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d028', 'artisan-demo', '会津塗', 'あいづぬり', '（架空）五十嵐 信', '下地から上塗りまで二十以上の工程を経る。一回塗るごとに一日から二日乾かして研ぐため、椀一つを仕上げるのに一ヶ月以上かかる。', null, '福島県', '福島県会津若松市', '会津塗は蒲生氏郷が漆器産業を奨励したのが始まりとされる。', '漆器,食器', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d029', 'artisan-demo', '香川漆器', 'かがわしっき', '（架空）三谷 修', '漆を彫って模様を出す蒟醤という技法を用いる。彫った溝に色漆を埋めて研ぎ出すため、模様が完成するまでに漆を塗っては研ぐ工程を十回以上繰り返す。', null, '香川県', '香川県高松市', '蒟醤は江戸後期に東南アジアの技法をもとに確立された。', '漆器,食器', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d030', 'artisan-demo', '琉球漆器', 'りゅうきゅうしっき', '（架空）玉城 憲一', '堆錦という沖縄独自の技法で、練った色漆を薄く延ばして文様を貼り付ける。デイゴやガジュマルなど南方の木を素地に使うことがある。', null, '沖縄県', '沖縄県那覇市', '琉球漆器は交易品として東南アジアの技法を取り入れた。', '漆器,食器', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d031', 'artisan-demo', '別府竹細工', 'べっぷたけざいく', '（架空）首藤 良介', '真竹を幅一ミリ程度のひごに割き、編んで籠を作る。編み方は二百種以上あるとされ、一つの籠に複数の編み方を組み合わせることが多い。', null, '大分県', '大分県別府市', '別府は温泉客の湯かご需要から竹細工が発展した。', '竹工,竹,かご', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d032', 'artisan-demo', '勝山竹細工', 'かつやまたけざいく', '（架空）加藤 誠治', '地元の真竹を油抜きしてから編む。花器や行灯を手がけ、ひごの幅を〇.五ミリ単位で揃えることで編み目を均一にしている。', null, '岡山県', '岡山県真庭市', '勝山は良質な真竹の産地として知られる。', '竹工,竹,花器', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d033', 'artisan-demo', '土佐虎斑竹細工', 'とさとらふだけざいく', '（架空）田内 修平', '虎の模様に似た斑点が出る虎斑竹だけを使う。斑点は自然にできるもので、良い斑の竹が育つ竹林はごく限られている。杖や花器に加工する。', null, '高知県', '高知県安芸市', '虎斑竹は安芸市の特定の竹林でしか育たないとされる。', '竹工,竹,杖', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d034', 'artisan-demo', '久留米絣', 'くるめがすり', '（架空）石橋 民江', '糸を先に染め分けてから織る絣織。柄を合わせるため、経糸と緯糸のくくり位置を〇.一ミリ単位で調整する。織り上げるまでに三十以上の工程を要する。', null, '福岡県', '福岡県久留米市', '久留米絣は江戸後期に一人の少女が考案したと伝わる。', '織物,布', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d035', 'artisan-demo', '弓浜絣', 'ゆみはまがすり', '（架空）門脇 智子', '木綿の糸を藍で染め、絵絣と呼ぶ具象的な柄を織り出す。柄がずれないよう、糸をくくる作業だけで数日かかる。織り手は現在数人にまで減っている。', null, '鳥取県', '鳥取県境港市', '弓浜絣は江戸後期に山陰地方で広まった。', '織物,布', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d036', 'artisan-demo', '伊予絣', 'いよがすり', '（架空）越智 保', '藍で染めた糸を織って幾何学模様を出す。柄合わせのため、織る前にくくった糸の位置を何度も確認する。かつて日本三大絣の一つに数えられた。', null, '愛媛県', '愛媛県松山市', '伊予絣は明治期に生産量日本一を記録した。', '織物,布', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d037', 'artisan-demo', '山形鋳物', 'やまがたいもの', '（架空）遠藤 一夫', '鋳型に溶かした鉄を流し込み、冷めたら型を割って取り出す。茶道具は肌が薄いのが特徴で、厚みを均一にするため型の隙間を〇.五ミリ単位で調整する。', null, '山形県', '山形県山形市', '山形鋳物は平安期に鋳物師が移り住んだのが始まりとされる。', '金工,鉄,茶道具', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d038', 'artisan-demo', '肥後象がん', 'ひごぞうがん', '（架空）松野 一馬', '鉄地に金や銀の細い線を打ち込んで模様を作る。地金に細かい溝を鏨で彫り、そこに金線を埋め込んで叩き締める。溝彫りだけで数日かかる。', null, '熊本県', '熊本県熊本市', '肥後象がんは刀や鐔の装飾として発展した。', '金工,銅,小物', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d039', 'artisan-demo', '津軽びいどろ', 'つがるびいどろ', '（架空）工藤 学', '千三百度で溶かしたガラスを竿に巻き取り、息を吹き込んで成形する宙吹き。色ガラスを重ねて模様を出す七宝技法も用いる。一点仕上げるのに数分だが、冷ますのに一晩かける。', null, '青森県', '青森県鰺ヶ沢町', '元は漁業用の浮き玉ガラスを作っていた技術を転用した。', 'ガラス,器,食器', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d040', 'artisan-demo', '肥前びーどろ', 'ひぜんびーどろ', '（架空）副島 誠', '宙吹きでガラスを成形し、道具を使わず息と重力だけで形を整える。竿を回す速さと息の量で厚みを調整するため、感覚がつかめるまで数年かかる。', null, '佐賀県', '佐賀県佐賀市', '肥前びーどろは幕末に精錬方で作られたのが始まり。', 'ガラス,器,酒器', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d041', 'artisan-demo', '琉球三線', 'りゅうきゅうさんしん', '（架空）平良 信一', '蛇皮を胴に張り、黒檀の棹を組む。皮張りは湿度で張り具合が変わるため天候を見て行う。棹の仕込みには数年寝かせた木材を使う。', null, '沖縄県', '沖縄県沖縄市', '琉球王国時代に中国から伝わった三弦が起源とされる。', '楽器,音が鳴る', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d042', 'artisan-demo', '薩摩琵琶', 'さつまびわ', '（架空）東郷 武志', '桑の木をくり抜いて胴を作り、絹糸の弦を張る。胴の厚みを削り出す作業だけで数週間かかり、木材は数年乾燥させたものを使う。', null, '鹿児島県', '鹿児島県鹿児島市', '薩摩琵琶は武士の士気を鼓舞する目的で広まったとされる。', '楽器,音が鳴る', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d043', 'artisan-demo', '燕鎚起銅器', 'つばめついきどうき', '（架空）玉木 一博', '一枚の銅板を金鎚で叩き絞りながら丸みのある器に仕上げる鎚起という技法。叩く回数は数千回に及び、急須一つで数週間かかる。継ぎ目を作らないため水漏れしない。', null, '新潟県', '新潟県燕市', '燕は江戸期に和釘作りから銅器へ発展した。', '金工,銅,急須', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d044', 'artisan-demo', '薩摩切子', 'さつまきりこ', '（架空）川原 誠', '色ガラスを被せたガラスを回転砥石で削り、文様を刻む。薩摩切子は色の層が江戸切子より厚く、削ると独特のぼかしが出る。一度途絶え、昭和末に復元された。', null, '鹿児島県', '鹿児島県鹿児島市', '幕末に薩摩藩が藩窯として始めたが、明治維新後に一度途絶えた。', 'ガラス,酒器,切子', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d045', 'artisan-demo', '大川組子', 'おおかわくみこ', '（架空）田中 洋二', '釘や接着剤を使わず、木を細かく組んで幾何学模様を作る建具の技術。一枚の欄間に千本近い部材を使うこともあり、〇.一ミリの誤差でも組めなくなる。', null, '福岡県', '福岡県大川市', '大川は江戸期から続く家具・建具の産地。', '木工,建具,家具', 'ja', 1788346810738, 1788346810738);
insert or ignore into cards (id, artisan_id, name, name_kana, artisan_name, description, hp_url, region, address, history, tags, lang, created_at, updated_at) values ('d046', 'artisan-demo', '遠刈田こけし', 'とおがったこけし', '（架空）佐藤 誠一', 'ろくろで胴を挽き、頭をはめ込んでから顔を描く。系統ごとに描き方の決まりがあり、遠刈田系は重ね菊の模様が特徴とされる。木は数年乾燥させてから使う。', null, '宮城県', '宮城県蔵王町', '遠刈田はこけし発祥の地の一つとされる。', '木工,人形,玩具', 'ja', 1788346810738, 1788346810738);
